					else
						instr[y].snum[sc] = smpReloc[nbu[sc]]+s;					
				}

				e++;

			}
			else
			{
				for (mp_sint32 i = 0; i < 120; i++)
					instr[y].snum[i] = -1;
			}

#ifdef MILKYTRACKER
			s+=16;
#else
			s+=instr[y].samp;
#endif				


		}

		header->smpnum=s;
		header->volenvnum=e;
		header->panenvnum=e;
